const derivedText = React.useMemo(() => {
  const strip = (html: any) => getPlainTextFromHTML(html || "");
  const clean = (html: any) => removeHtmlAndNewline(html);
  return {
    adminNotes: clean(Dataimp?.AdminNotes),
    body: clean(Dataimp?.Body),
    shortDesc: clean(Dataimp?.Short_x0020_Description_x0020_On),
    background: strip(Dataimp?.Background),
    idea: strip(Dataimp?.Idea),
    valueAdded: strip(Dataimp?.ValueAdded),
    helpInfo: strip(Dataimp?.Help_x0020_Information),
    technical: strip(Dataimp?.TechnicalExplanations),
    deliverables: strip(Dataimp?.Deliverables),
  };
}, [Dataimp]);

